/**
 * build-all-reactors.js — Deploy remaining reactors + mint all positions sequentially.
 * Phase 1: Deploy PKT, EGP, OGC, IGS, DHG reactors
 * Phase 2: Mint positions for BTN (4 remaining), LGP (7), PKT (7), EGP (7), OGC (7), IGS (7), DHG (7)
 * 100K of nation token per position. Creates missing V3 pools as needed.
 * Skips pairs where token balance is zero.
 */
const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '.env') });
const ethers = require('ethers');

const RPC = process.env.POLYGON_RPC || 'https://polygon-rpc.com';
const PK  = process.env.BALANCER_PRIVATE_KEY;

const NPM = '0xC36442b4a4522E871399CD717aBDD847Ab11FE88';
const V3_FACTORY = '0x1F98431c8aD98523631AE4a59f267346ea31F984';
const ROUTER = '0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45';
const FEE = 10000;
const TICK_LOW = -887200;
const TICK_HIGH = 887200;

const TOKENS = {
  DDD: { addr: '0x4bf82cf0d6b2afc87367052b793097153c859d38', dec: 18 },
  EGP: { addr: '0x64f6f111e9fdb753877f17f399b759de97379170', dec: 18 },
  OGC: { addr: '0xccf37622e6b72352e7b410481dd4913563038b7c', dec: 18 },
  IGS: { addr: '0xe302672798d12e7f68c783db2c2d5e6b48ccf3ce', dec: 8 },
  BTN: { addr: '0xd7c584d40216576f1d8651eab8bef9de69497666', dec: 8 },
  LGP: { addr: '0xddc330761761751e005333208889bfe36c6e6760', dec: 18 },
  DHG: { addr: '0x75c0a194cd8b4f01d5ed58be5b7c5b61a9c69d0a', dec: 8 },
  PKT: { addr: '0x8a088dceecbcf457762eb7c66f78fff27dc0c04a', dec: 18 },
};

// Already deployed
const REACTORS = {
  DDD: '0x0d8389435abACD28410AD240613572E3d3573ADE',
  BTN: '0x2b35C282c21cE95C6050254318044DF530079521',
  LGP: '0xAcbC4df046AC437c75EE020A534740dd5e425E41',
};

// BTN already has DDD, EGP, OGC, IGS — skip those
const BTN_DONE = ['DDD', 'EGP', 'OGC', 'IGS'];

const DEPLOY_ABI = [
  {"inputs":[{"internalType":"address","name":"_nationToken","type":"address"},{"internalType":"address","name":"_pm","type":"address"},{"internalType":"address","name":"_router","type":"address"}],"stateMutability":"nonpayable","type":"constructor"},
  {"inputs":[],"name":"poolCount","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},
  {"inputs":[],"name":"nationToken","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},
  {"inputs":[],"name":"admin","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},
];

const BYTECODE = "";

const ERC20_ABI = [
  'function balanceOf(address) view returns (uint256)',
  'function approve(address,uint256) returns (bool)',
  'function allowance(address,address) view returns (uint256)',
];
const NPM_ABI = [
  'function mint((address token0,address token1,uint24 fee,int24 tickLower,int24 tickUpper,uint256 amount0Desired,uint256 amount1Desired,uint256 amount0Min,uint256 amount1Min,address recipient,uint256 deadline)) payable returns (uint256 tokenId,uint128 liquidity,uint256 amount0,uint256 amount1)',
  'function safeTransferFrom(address,address,uint256)',
];
const REACTOR_ABI = [
  'function addPool(uint256) external',
  'function poolCount() view returns (uint256)',
];
const FACTORY_ABI = [
  'function getPool(address,address,uint24) view returns (address)',
  'function createPool(address,address,uint24) returns (address)',
];
const POOL_ABI = [
  'function initialize(uint160 sqrtPriceX96)',
];

function log(msg) { console.log('[' + new Date().toLocaleTimeString() + '] ' + msg); }
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

// Get boosted gas params (2x current) to avoid stuck txs on Polygon
async function gasOverrides(provider) {
  const fee = await provider.getFeeData();
  return {
    maxFeePerGas: fee.maxFeePerGas * 2n,
    maxPriorityFeePerGas: fee.maxPriorityFeePerGas * 2n,
  };
}

function getSqrtPriceX96(dec0, dec1) {
  const Q96 = 2n ** 96n;
  const decDiff = dec1 - dec0;
  if (decDiff === 0) return Q96;
  if (decDiff === 10) return Q96 * 100000n;
  if (decDiff === -10) return Q96 / 100000n;
  return Q96; // fallback for unexpected
}

async function ensurePool(factory, wallet, provider, addrA, addrB, decA, decB) {
  const ZERO = '0x0000000000000000000000000000000000000000';
  let poolAddr = await factory.getPool(addrA, addrB, FEE);
  if (poolAddr !== ZERO) return;

  log('  Creating V3 1% pool...');
  const gas = await gasOverrides(provider);
  const tx = await factory.createPool(addrA, addrB, FEE, gas);
  await tx.wait();
  poolAddr = await factory.getPool(addrA, addrB, FEE);
  log('  Pool: ' + poolAddr);

  const t0isA = addrA.toLowerCase() < addrB.toLowerCase();
  const dec0 = t0isA ? decA : decB;
  const dec1 = t0isA ? decB : decA;
  const sqrtPrice = getSqrtPriceX96(dec0, dec1);

  const pool = new ethers.Contract(poolAddr, POOL_ABI, wallet);
  const tx2 = await pool.initialize(sqrtPrice, await gasOverrides(provider));
  await tx2.wait();
  log('  Initialized');
}

async function main() {
  const provider = new ethers.JsonRpcProvider(RPC);
  const wallet = new ethers.Wallet(PK, provider);
  const npm = new ethers.Contract(NPM, NPM_ABI, wallet);
  const factory = new ethers.Contract(V3_FACTORY, FACTORY_ABI, wallet);

  log('Wallet: ' + wallet.address);

  // ============ PHASE 1: Deploy missing reactors ============
  const toDeploy = ['PKT', 'EGP', 'OGC', 'IGS', 'DHG'];
  log('\n====== PHASE 1: DEPLOYING ' + toDeploy.length + ' REACTORS ======');

  for (const name of toDeploy) {
    if (REACTORS[name]) { log(name + ' already deployed: ' + REACTORS[name]); continue; }
    log('\nDeploying ' + name + ' reactor...');
    const f = new ethers.ContractFactory(DEPLOY_ABI, BYTECODE, wallet);
    const gas = await gasOverrides(provider);
    const contract = await f.deploy(TOKENS[name].addr, NPM, ROUTER, gas);
    await contract.waitForDeployment();
    const addr = await contract.getAddress();
    REACTORS[name] = addr;
    log(name + ' REACTOR: ' + addr);
  }

  log('\n--- All reactor addresses ---');
  for (const [name, addr] of Object.entries(REACTORS)) {
    log('  ' + name + ': ' + addr);
  }

  // ============ PHASE 2: Approve all tokens ============
  log('\n====== PHASE 2: APPROVALS ======');
  for (const [name, t] of Object.entries(TOKENS)) {
    const c = new ethers.Contract(t.addr, ERC20_ABI, wallet);
    const allow = await c.allowance(wallet.address, NPM);
    if (allow < ethers.parseUnits('10000000', t.dec)) {
      log('Approving ' + name + '...');
      const tx = await c.approve(NPM, ethers.MaxUint256, await gasOverrides(provider));
      await tx.wait();
    }
  }
  log('All tokens approved');

  // ============ PHASE 3: Mint positions ============
  log('\n====== PHASE 3: MINTING POSITIONS ======');

  // Order: BTN first (4 remaining), then LGP, PKT, EGP, OGC, IGS, DHG
  const ORDER = ['BTN', 'LGP', 'PKT', 'EGP', 'OGC', 'IGS', 'DHG'];
  // DDD reactor is already complete (12 pools)

  let totalMinted = 0;
  const skipped = [];

  for (const nation of ORDER) {
    const reactorAddr = REACTORS[nation];
    if (!reactorAddr) { log('SKIP ' + nation + ' — no reactor'); continue; }

    const reactor = new ethers.Contract(reactorAddr, REACTOR_ABI, wallet);
    const existingCount = Number(await reactor.poolCount());
    const nationT = TOKENS[nation];
    const AMOUNT = ethers.parseUnits('100000', nationT.dec);

    log('\n========== ' + nation + ' REACTOR (' + existingCount + ' existing) ==========');

    const pairs = Object.keys(TOKENS).filter(n => n !== nation);
    // Skip already-done pairs for BTN
    const skipPairs = nation === 'BTN' ? BTN_DONE : [];

    for (const pairName of pairs) {
      if (skipPairs.includes(pairName)) {
        log('  ' + nation + '/' + pairName + ' — already done, skip');
        continue;
      }

      const pairT = TOKENS[pairName];

      // Check nation balance
      const nationC = new ethers.Contract(nationT.addr, ERC20_ABI, wallet);
      const nationBal = await nationC.balanceOf(wallet.address);
      if (nationBal < AMOUNT) {
        const s = nation + '/' + pairName + ' (only ' + Number(ethers.formatUnits(nationBal, nationT.dec)).toLocaleString() + ' ' + nation + ')';
        log('  SKIP ' + s);
        skipped.push(s);
        continue;
      }

      // Check pair balance
      const pairC = new ethers.Contract(pairT.addr, ERC20_ABI, wallet);
      const pairBal = await pairC.balanceOf(wallet.address);
      if (pairBal === 0n) {
        log('  SKIP ' + nation + '/' + pairName + ' — zero ' + pairName);
        skipped.push(nation + '/' + pairName + ' (zero ' + pairName + ')');
        continue;
      }

      // Use min(balance, 100K) of pair token
      const pair100k = ethers.parseUnits('100000', pairT.dec);
      const pairUse = pairBal < pair100k ? pairBal : pair100k;

      log('\n  --- ' + nation + '/' + pairName + ' ---');
      log('  ' + nation + ': 100K | ' + pairName + ': ' + Number(ethers.formatUnits(pairUse, pairT.dec)).toLocaleString());

      // Ensure pool exists
      try {
        await ensurePool(factory, wallet, provider, nationT.addr, pairT.addr, nationT.dec, pairT.dec);
      } catch (e) {
        log('  Pool creation error: ' + (e.shortMessage || e.message).slice(0, 120));
        skipped.push(nation + '/' + pairName + ' (pool error)');
        continue;
      }

      // Token ordering
      const nationLower = nationT.addr.toLowerCase() < pairT.addr.toLowerCase();
      const token0 = nationLower ? nationT.addr : pairT.addr;
      const token1 = nationLower ? pairT.addr : nationT.addr;
      const amount0 = nationLower ? AMOUNT : pairUse;
      const amount1 = nationLower ? pairUse : AMOUNT;

      try {
        const deadline = Math.floor(Date.now() / 1000) + 600;
        const gas = await gasOverrides(provider);
        const tx = await npm.mint({
          token0, token1, fee: FEE,
          tickLower: TICK_LOW, tickUpper: TICK_HIGH,
          amount0Desired: amount0, amount1Desired: amount1,
          amount0Min: 0n, amount1Min: 0n,
          recipient: wallet.address, deadline,
        }, gas);
        const receipt = await tx.wait();
        const transferTopic = ethers.id('Transfer(address,address,uint256)');
        const mintLog = receipt.logs.find(l =>
          l.address.toLowerCase() === NPM.toLowerCase() && l.topics[0] === transferTopic
        );
        const tokenId = BigInt(mintLog.topics[3]);
        log('  MINTED #' + tokenId.toString());

        // Transfer to reactor
        const tx2 = await npm.safeTransferFrom(wallet.address, reactorAddr, tokenId, await gasOverrides(provider));
        await tx2.wait();
        log('  Transferred');

        // Register
        const tx3 = await reactor.addPool(tokenId, await gasOverrides(provider));
        await tx3.wait();
        const newCount = await reactor.poolCount();
        log('  addPool done — ' + nation + ' reactor: ' + newCount.toString() + ' pools');
        totalMinted++;

        // 2 min delay between positions
        log('  Waiting 2 min...');
        await sleep(120000);
      } catch (e) {
        log('  ERROR: ' + (e.shortMessage || e.message).slice(0, 200));
        skipped.push(nation + '/' + pairName + ' (mint error)');
      }
    }
  }

  // ============ SUMMARY ============
  log('\n\n========================================');
  log('COMPLETE — ' + totalMinted + ' positions minted');
  if (skipped.length > 0) {
    log('\nSkipped (' + skipped.length + '):');
    skipped.forEach(s => log('  - ' + s));
  }
  log('\nFinal reactor pool counts:');
  for (const [name, addr] of Object.entries(REACTORS)) {
    const r = new ethers.Contract(addr, REACTOR_ABI, provider);
    const c = await r.poolCount();
    log('  ' + name + ': ' + c.toString() + ' pools');
  }
}

main().catch(e => { console.error('Fatal:', e.shortMessage || e.message); process.exit(1); });
